/** The Youniversal [ColorScheme] for [style], resolved against the system dark mode. */
public fun youniversalColorScheme(
    style: YouniversalBackgroundStyle,
    isSystemInDarkTheme: Boolean = false,
): ColorScheme = when (style.resolve(isSystemInDarkTheme)) {
    YouniversalBackgroundStyle.Light -> youniversalLightColorScheme()
    YouniversalBackgroundStyle.Dark -> youniversalDarkColorScheme()
    YouniversalBackgroundStyle.Cream -> youniversalCreamColorScheme()
    YouniversalBackgroundStyle.Auto -> youniversalLightColorScheme()
}

/**
 * Raises a scheme to Youniversal high contrast: deeper foreground colors, a stronger
 * outline and flat (untinted) containers so boundaries stay legible in bright light.
 */
public fun ColorScheme.youniversalHighContrast(isDark: Boolean): ColorScheme =
    if (isDark) {
        copy(
            onBackground = Color.White,
            onSurface = Color.White,
            onSurfaceVariant = onSurfaceVariant.youniversalLighten(0.22f),
            outline = outline.youniversalLighten(0.28f),
            outlineVariant = outlineVariant.youniversalLighten(0.16f),
            surfaceVariant = surfaceVariant.youniversalDarken(0.25f),
            surfaceContainer = surfaceContainer.youniversalDarken(0.35f),
            surfaceContainerHigh = surfaceContainerHigh.youniversalDarken(0.35f),
            surfaceContainerHighest = surfaceContainerHighest.youniversalDarken(0.35f),
        )
    } else {
        copy(
            onBackground = Color.Black,
            onSurface = Color.Black,
            onSurfaceVariant = onSurfaceVariant.youniversalDarken(0.22f),
            outline = outline.youniversalDarken(0.30f),
            outlineVariant = outlineVariant.youniversalDarken(0.18f),
            surfaceVariant = surfaceVariant.youniversalLighten(0.20f),
            surfaceContainer = surfaceContainer.youniversalLighten(0.30f),
            surfaceContainerHigh = surfaceContainerHigh.youniversalLighten(0.30f),
            surfaceContainerHighest = surfaceContainerHighest.youniversalLighten(0.30f),
        )
    }

/**
 * Keeps the Material You accent roles but swaps in the Cream neutral ramp, so a
 * wallpaper-derived palette still sits on aged paper.
 */
public fun ColorScheme.withCreamNeutrals(cream: ColorScheme = youniversalCreamColorScheme()): ColorScheme =
    copy(
        background = cream.background,
        onBackground = cream.onBackground,
        surface = cream.surface,
        onSurface = cream.onSurface,
        surfaceVariant = cream.surfaceVariant,
        onSurfaceVariant = cream.onSurfaceVariant,
        surfaceBright = cream.surfaceBright,
        surfaceDim = cream.surfaceDim,
        surfaceContainer = cream.surfaceContainer,
        surfaceContainerHigh = cream.surfaceContainerHigh,
        surfaceContainerHighest = cream.surfaceContainerHighest,
        surfaceContainerLow = cream.surfaceContainerLow,
        surfaceContainerLowest = cream.surfaceContainerLowest,
        inverseSurface = cream.inverseSurface,
        inverseOnSurface = cream.inverseOnSurface,
        outline = cream.outline,
        outlineVariant = cream.outlineVariant,
    )
